#include "ksGlobalEffectTask.h"
#include <array>
#include <iostream>
#include <stdexcept>
static void check(bool b){if(!b)throw std::runtime_error("Global effect property failed");}
int main(){using T=ks::GlobalEffectTask;using C=T::Child;uint64_t cases=0;auto verify=[&](unsigned flags,unsigned amount,unsigned time,unsigned toggle,uint32_t coefficient){T t;std::array<C,6> order{C::Initial,C::Coefficient,C::FirstB,C::SecondB,C::FirstA,C::SecondA};unsigned children=0,guard=0,amountReads=0;auto read=[&](T::Read r)->uint32_t{switch(r){case T::Read::Flags:return flags;case T::Read::Amount:++amountReads;return amount;case T::Read::Time:return time;case T::Read::Toggle:return toggle;}return 0;};while(t.stage()!=T::Stage::Complete){check(++guard<64);auto c=t.child();if(c!=C::None){check(children<order.size()&&c==order[children]);if(c==C::Initial)check(t.initialWireWord()==((flags&32)?uint32_t(uint16_t(amount*230+0x666))<<8:0));if(c==C::Coefficient)check(t.input()==unsigned(uint8_t(time+104))*170);if(c==C::FirstA||c==C::FirstB)check(t.first()==(toggle?0:coefficient));if(c==C::SecondA||c==C::SecondB)check(t.second()==(toggle?coefficient:0));check(t.resumeChild(coefficient));++children;continue;}auto cost=t.nextClocks(),s=unsigned(t.stage());check(t.advanceBefore(cost-1,read)==0&&unsigned(t.stage())==s);check(t.advanceBefore(cost,read)==cost);}check(children==6&&amountReads==unsigned(bool(flags&32)));++cases;};for(unsigned flags=0;flags<256;++flags)for(unsigned toggle=0;toggle<256;++toggle)verify(flags,127,255,toggle,(flags<<24)|(toggle*0x010101u));for(unsigned amount=0;amount<256;++amount)for(unsigned time=0;time<256;++time)verify(32,amount,time,time&1,0x7fffff00);std::cout<<"PASS: "<<cases<<" pure effect properties; all flags/toggles and amount/time pairs, initial flags gate, wrapped coefficient input, arbitrary32-bit coefficient routing, exact B5/B6/A5/A6 order,6child lifetime, budget refusal\n";}
